<?php
declare(strict_types=1);$dbName=getenv('DB_NAME')?:'';if(!str_ends_with($dbName,'_test')&&!preg_match('/(^|_)dev(elopment)?$/i',$dbName))throw new RuntimeException('Tax Declaration seeder refuses non-development/test databases.');
if(!isset($conn)||!$conn instanceof mysqli){require __DIR__.'/../includes/db.php';}$admin=(int)$conn->query("SELECT id FROM users WHERE role='admin' ORDER BY id LIMIT 1")->fetch_row()[0];$land=(int)$conn->query("SELECT id FROM property_types WHERE code='land'")->fetch_row()[0];$parcel=(int)$conn->query('SELECT id FROM ip_land_parcels ORDER BY id LIMIT 1')->fetch_row()[0];
function seed_td(mysqli$c,array$d):int{$stmt=$c->prepare('SELECT id FROM tax_declarations WHERE td_number=?');$stmt->bind_param('s',$d['number']);$stmt->execute();if($r=$stmt->get_result()->fetch_row())return(int)$r[0];$stmt=$c->prepare("INSERT INTO tax_declarations(td_number,pin,owning_tribe,owner_name,location_barangay,property_type_id,tax_status,effectivity_year,parcel_id,previous_td_arp_number,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$stmt->bind_param('sssssisiisii',$d['number'],$d['pin'],$d['scope'],$d['owner'],$d['barangay'],$d['type'],$d['status'],$d['year'],$d['parcel'],$d['previous'],$d['user'],$d['user']);$stmt->execute();return(int)$c->insert_id;}
$old=seed_td($conn,['number'=>'ANON-TD-OLD-001','pin'=>null,'scope'=>'Test Tribe','owner'=>'Fictional Former Owner','barangay'=>'Sample Barangay','type'=>$land,'status'=>'taxable','year'=>2018,'parcel'=>null,'previous'=>null,'user'=>$admin]);$new=seed_td($conn,['number'=>'ANON-TD-CURRENT-001','pin'=>'ANON-PIN-001','scope'=>'Test Tribe','owner'=>'Fictional Landholder','barangay'=>'Test Barangay','type'=>$land,'status'=>'taxable','year'=>2026,'parcel'=>$parcel,'previous'=>'ANON-TD-OLD-001','user'=>$admin]);$conn->query("UPDATE tax_declarations SET declaration_status='historical' WHERE id=$old");$conn->query("UPDATE tax_declarations SET previous_tax_declaration_id=$old WHERE id=$new");
if((int)$conn->query("SELECT COUNT(*) FROM tax_declaration_assessments WHERE tax_declaration_id=$new")->fetch_row()[0]===0){$conn->query("INSERT INTO tax_declaration_assessments(tax_declaration_id,classification,area_sqm,market_value,actual_use,assessment_level_percent,assessed_value) VALUES ($new,'Agricultural',1250.5000,250000.00,'Agricultural',20.00,50000.00),($new,'Residential',300.0000,180000.00,'Residential',15.00,27000.00)");}echo "Anonymized Tax Declaration fixtures ready.\n";
